const l={ui:{fig:"Рис. 2",title:"Вырезанные уголки",svgLabel:"Изометрический рисунок того, как делаются вырезанные уголки: деталь сложена пополам и стачана по бокам, из каждого нижнего уголка вырезан кусочек 3,5 × 2,5 см, уголок раскрыт так, что боковой шов лёг на сгиб дна, и прострочен поперёк, сумка вывернута — дно ровное.",prev:"Предыдущий шаг",dot:(t,e)=>t?`Шаг ${t}: ${e}`:e,start:"Шаги →",next:"Дальше →",overview:"Обзор",stepOf:(t,e)=>`Шаг ${t} из ${e}`,machine:t=>`Машина: ${t.toLowerCase()}`,inThisStep:"В этом шаге",takeApart:"Поставить",putTogether:"Показать дно",replay:"↻ Повторить",parts:"Детали",allSteps:"Пошаговая инструкция",endView:"ВИД С ТОРЦА"},stitches:{straight:"Прямая строчка"},labels:{cm23:"23 см",cm31:"31 см",rightSides:"лицом к лицу",foldBottom:"сгиб — это дно",seam05:"шов 0,5 см",cm35:"3,5 см",cm25:"2,5 см",cutBoth:"вырезать через оба слоя",seamOnFold:"шов на сгиб",sewAcross:"прострочить поперёк",bothCorners:"оба уголка",turnOut:"вывернуть на лицо",flatBottom:"ровное дно",cornerSeam:"шов уголка"},steps:[{title:"Вырезанные уголки",text:"Дно косметички, сумка перевёрнута: ровное дно, и на каждом его конце — короткий шов поперёк, там, где боковой шов встречается со сгибом дна. Нажмите на сумку, чтобы её поставить."},{title:"Сложить пополам",text:"Косметичка — это одна деталь 23 × 31 см. Сложите её пополам поперёк длины, лицом к лицу: сгиб — это дно.",details:["Положите деталь 23 × 31 см лицом вверх.","Сложите её пополам поперёк длины, лицом к лицу. Сгиб — это дно сумки, шва на дне нет.","Подклад косметички — такая же деталь 23 × 31 см, и делается он так же."]},{title:"Стачать бока",text:"Стачайте оба бока швом 0,5 см — от верха до сгиба.",details:["Сколите бока зажимами.","Стачайте оба боковых шва в 0,5 см от края, до самого сгиба.","У косметички до этого вшита молния, а в одном боковом шве подклада оставлено отверстие для выворачивания; уголки делаются так же."]},{title:"Вырезать уголки",text:"Из каждого нижнего уголка вырежьте кусочек 3,5 × 2,5 см: 3,5 см вдоль дна, 2,5 см вдоль бокового шва.",details:["Наметьте в каждом нижнем уголке прямоугольник 3,5 × 2,5 см: 3,5 см вдоль сгиба дна, 2,5 см вверх по боковому шву.","Вырежьте его сразу через оба слоя.","У косметички таких уголков четыре: два у верха и два у подклада."]},{title:"Раскрыть уголок",text:"Раскройте каждый вырезанный уголок и сложите так, чтобы боковой шов лёг на сгиб дна: срезы лягут в одну прямую линию.",details:["Раскройте вырезанный уголок, разводя перед и спинку.","Сложите его так, чтобы боковой шов лёг точно на сгиб дна.","Срезы теперь лежат в одну прямую линию поперёк уголка."]},{title:"Прострочить поперёк",text:"Прострочите каждый уголок поперёк, в 0,5 см от среза.",details:["Прострочите уголок поперёк, в 0,5 см от края.","Так же второй уголок — а у косметички ещё и два уголка подклада."]},{title:"Вывернуть",text:"Выверните сумку на лицо: дно ровное, а на каждом его конце — короткий шов уголка.",details:["Выверните сумку на лицо (косметичку выворачивают через отверстие в подкладе) и выправьте уголки.","Дно ровное. На каждом конце боковой шов приходит в середину шва уголка."]}],legend:[{title:"Дно",text:"ровное · между двумя швами уголков"},{title:"Сгиб дна",text:"деталь 23 × 31 см сложена пополам · шва на дне нет"},{title:"Швы уголков",text:"прострочены поперёк в 0,5 см от края, после того как из уголка вырезан кусочек 3,5 × 2,5 см"},{title:"Боковые швы",text:"0,5 см · каждый приходит в середину шва уголка"}]};export{l as default};
